-- Bahbah warehouse seed: in-store system products with barcodes
-- Run AFTER security.sql and commerce.sql on the STAGING Supabase project
create table if not exists public.warehouse_products (code text, barcode text, name_ar text, name_en text, active_ingredient text, strength text, form text, category text, sale_price numeric, cost_price numeric, stock_boxes numeric, stock_strips numeric, min_limit numeric);
create index if not exists warehouse_products_barcode_idx on public.warehouse_products (barcode);
alter table public.warehouse_products enable row level security;
